typedef struct {
    enum { CARD, TRANSFER } tag;
    union { struct { char number[20]; } card;
            struct { char iban[34]; }   transfer; };
} payment_t;
const char *describe(const payment_t *p) {
    switch (p->tag) {              /* -Wswitch-enum: warn on an unhandled tag */
    case CARD:     return p->card.number;
    case TRANSFER: return p->transfer.iban;
    }
    return "unreachable";
}
